// 修复方案1：使用 spawn 而不是 exec
// spawn 不是通过 Shell 执行命令，而是直接创建子进程
export async function pingHost(target: string): Promise<string> {
	const { stdout } = await spawn('ping', ['-c', '4', target])
	return stdout.toString()
}

