import { exec, spawn } from "child_process"
import { promisify } from "util"

const execAsync = promisify(exec)

// IP 地址验证函数
function isValidIPv4(target: string): boolean {
	const ipv4Pattern = /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/
	return ipv4Pattern.test(target)
}

export async function pingHost(target: string): Promise<string> {
	// ✅ 添加输入验证
	if (!isValidIPv4(target)) {
		throw new Error('Invalid IP address format')
	}

	// ✅ 使用参数化执行，而不是字符串拼接
	const { stdout } = await execAsync('ping', ['-c', '4', target])
	return stdout
}

// 修复方案3：使用 spawn（推荐方案）
// spawn 更安全，因为它不会通过 Shell 解析命令
export async function pingHost(target: string): Promise<string> {
	// ✅ 输入验证
	if (!isValidIPv4(target)) {
		throw new Error('Invalid IP address format')
	}

	// ✅ 使用 spawn 的参数化 API
	return new Promise((resolve, reject) => {
		spawn('ping', ['-c', '4', target], {
			encoding: 'utf8'
		}).on('error', reject)
			.stdout.on('data', (data) => {
				resolve(data.toString())
			})
			.stderr.on('data', (data) => {
				reject(new Error(data.toString()))
			})
			.on('close', (code) => {
				if (code !== 0) {
					reject(new Error(`ping process exited with code ${code}`))
				}
			})
	})
}

// 修复方案4：使用第三方安全库（如 escape-shell）
import { exec } from "child_process"
import { promisify } from "util"
import { escape } from 'shell-escape'

const execAsync = promisify(exec)

export async function pingHost(target: string): Promise<string> {
	// ✅ 使用 shell-escape 转义特殊字符
	const escapedTarget = escape([target])
	const command = `ping -c 4 ${escapedTarget}`
	const { stdout } = await execAsync(command)
	return stdout
}

